        const fullyVisible = rect.top >= boundary.top - 1 && rect.bottom <= boundary.bottom + 1 &&
          rect.left >= boundary.left - 1 && rect.right <= boundary.right + 1 &&
          rect.top >= -1 && rect.bottom <= innerHeight + 1 && rect.left >= -1 && rect.right <= innerWidth + 1
