        left: +rect.left.toFixed(1), top: +rect.top.toFixed(1),
        right: +rect.right.toFixed(1), bottom: +rect.bottom.toFixed(1),
        width: +rect.width.toFixed(1), height: +rect.height.toFixed(1),
